package vn.codegrade.judge;
import vn.codegrade.db.Store;import vn.codegrade.auth.Identity.User;import java.security.*;import java.security.spec.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class ReceiptLedger {
 public static Object sign(Store db,String id,String owner,Object payload){try{
  if(db.sql.queryForObject("SELECT COUNT(*) FROM signing_keys",Integer.class)==0){var pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();db.sql.update("INSERT INTO signing_keys VALUES(1,?,?)",Base64.getEncoder().encodeToString(pair.getPrivate().getEncoded()),Base64.getEncoder().encodeToString(pair.getPublic().getEncoded()));}
  var key=db.one("SELECT * FROM signing_keys WHERE id=1");String body=db.write(payload);var signer=Signature.getInstance("Ed25519");signer.initSign(KeyFactory.getInstance("Ed25519").generatePrivate(new PKCS8EncodedKeySpec(Base64.getDecoder().decode((String)key.get("private_key")))));signer.update(body.getBytes(StandardCharsets.UTF_8));String signature=Base64.getEncoder().encodeToString(signer.sign());db.sql.update("INSERT INTO receipts VALUES(?,?,?,?)",id,owner,body,signature);return Map.of("payload",body,"signature",signature,"publicKey",key.get("public_key"));
 }catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
 public static Object get(Store db,User u,String id){var r=db.one("SELECT * FROM receipts WHERE submission_id=?",id);Store.require(r.get("owner_id").equals(u.id())||u.admin(),"Receipt access denied");return Map.of("payload",r.get("payload"),"signature",r.get("signature"),"publicKey",db.one("SELECT public_key FROM signing_keys WHERE id=1").get("public_key"));}
 public static void closeRound(Store db,com.fasterxml.jackson.databind.node.ObjectNode room){String round=room.path("current").path("id").asText();if(round.isEmpty())return;var admitted=db.sql.queryForList("SELECT id,user_id,received_at,admission_order,status,score FROM submissions WHERE round_id=? AND mode='OFFICIAL' ORDER BY received_at,admission_order",round);String id=db.id();Object proof=sign(db,id,room.path("hostId").asText(),Map.of("roundId",round,"deadline",room.path("current").path("deadline").asLong(),"admitted",admitted,"state",room.path("state").asText()));room.set("certificate",db.tree(proof));}
}